import sys, json
try:
    data = json.loads(sys.stdin.read())
except ValueError:
    raise SystemExit(1)
if not isinstance(data, dict):
    raise SystemExit(1)
if not isinstance(data.get("state"),dict) or type(data["state"].get("saved")) is not bool or not isinstance(data.get("title"),str):
    raise SystemExit(1)
def apply_action(state,title):
    result = dict(state)
    if title.strip():
        result["saved"] = True
    return result
print(apply_action(data["state"],data["title"])["saved"])
print(data["state"]["saved"])
